steps.body:
A **graph** is a set of nodes joined by edges: people and friendships, towns and roads, courses and prerequisites. The usual way to store one is an **adjacency list**, a Map from each node to an array of its neighbors.

```javascript
function addEdge(graph, a, b) {
  if (!graph.has(a)) {
    graph.set(a, []);
  }
  if (!graph.has(b)) {
    graph.set(b, []);
  }
  graph.get(a).push(b);
  graph.get(b).push(a);
}
```

In an **undirected** graph every edge works both ways, so you push it in both directions. Create a missing entry before pushing: for a new node `graph.get(a)` is `undefined`, and calling `push` on it throws a TypeError. A node's **degree** is its number of neighbors, `graph.get(a).length`.

A Map remembers insertion order and neighbors arrive in input order, so sort before printing: `[...graph.keys()].sort((a, b) => a.localeCompare(b))` for the nodes and `toSorted` for each neighbor list. Prefer a Map over a plain object, so a node named `constructor` cannot clash with inherited keys.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const edges = input.trim().split("\n").map((line) => line.trim().split(/\s+/));

function addEdge(graph, a, b) {
  if (!graph.has(a)) {
    graph.set(a, []);
  }
  if (!graph.has(b)) {
    graph.set(b, []);
  }
  graph.get(a).push(b);
  graph.get(b).push(a);
}

const graph = new Map();
for (const [a, b] of edges) {
  addEdge(graph, a, b);
}

const people = [...graph.keys()].sort((a, b) => a.localeCompare(b));
let best = people[0];
for (const person of people) {
  const friends = graph.get(person).toSorted((a, b) => a.localeCompare(b));
  console.log(`${person} (${friends.length}): ${friends.join(", ")}`);
  if (friends.length > graph.get(best).length) {
    best = person;
  }
}
console.log(`Most connected: ${best}`);

