steps.body:
To find everything reachable from a node, run a traversal with a **visited** Set. Mark a node when you push it, so it is never added twice:

```javascript
function explore(graph, start, visited) {
  const members = [];
  const stack = [start];
  visited.add(start);
  while (stack.length > 0) {
    const node = stack.pop();
    members.push(node);
    for (const next of graph.get(node)) {
      if (!visited.has(next)) {
        visited.add(next);
        stack.push(next);
      }
    }
  }
  return members;
}
```

This is the iterative DFS from the Depth-First Search lesson, with `graph.get(node)` in place of the four directions. The graph is an adjacency list: a Map from each node to an array of its neighbors. A queue instead of a stack (BFS) finds the same members.

A **connected component** is a group of nodes that can all reach each other. Loop over every node and start `explore` from each one that is still unvisited, sharing one visited Set: every fresh start is a new component, and `explore` returns its members. Two nodes are connected when a traversal from one reaches the other: `explore(graph, a, new Set()).includes(b)`.

**The gotcha:** without the visited Set, a cycle such as a, b, c, a sends the loop around forever.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const edgeCount = Number(lines[0]);
const edges = lines.slice(1, edgeCount + 1).map((line) => line.trim().split(/\s+/));
const [from, to] = lines[edgeCount + 1].trim().split(/\s+/);

function addEdge(graph, a, b) {
  if (!graph.has(a)) {
    graph.set(a, []);
  }
  if (!graph.has(b)) {
    graph.set(b, []);
  }
  graph.get(a).push(b);
  graph.get(b).push(a);
}

function explore(graph, start, visited) {
  const members = [];
  const stack = [start];
  visited.add(start);
  while (stack.length > 0) {
    const node = stack.pop();
    members.push(node);
    for (const next of graph.get(node)) {
      if (!visited.has(next)) {
        visited.add(next);
        stack.push(next);
      }
    }
  }
  return members;
}

const graph = new Map();
for (const [a, b] of edges) {
  addEdge(graph, a, b);
}

const visited = new Set();
const components = [];
for (const node of [...graph.keys()].sort((a, b) => a.localeCompare(b))) {
  if (!visited.has(node)) {
    components.push(explore(graph, node, visited).sort((a, b) => a.localeCompare(b)));
  }
}

console.log(`Components: ${components.length}`);
for (const members of components) {
  console.log(members.join(" "));
}
const connected = explore(graph, from, new Set()).includes(to);
console.log(`${from} and ${to} connected: ${connected ? "yes" : "no"}`);

