    graph.set(a, []);
  }
  if (!graph.has(b)) {
    graph.set(b, []);
  }
  graph.get(a).push(b);
  graph.get(b).push(a);
}

function explore(graph, start, visited) {
  const members = [];
  const stack = [start];
  visited.add(start);
  while (stack.length > 0) {
    const node = stack.pop();
    members.push(node);
    for (const next of graph.get(node)) {
      if (!visited.has(next)) {
        visited.add(next);
        stack.push(next);
      }
    }
  }
  return members;
}

const graph = new Map();
for (const [a, b] of edges) {
  addEdge(graph, a, b);
}

const visited = new Set();
let componentCount = 0;
