steps.body:
In an unweighted graph, BFS from a source reaches nodes in order of distance, so the first time it discovers a node it has found a path with the fewest edges. To rebuild that path, record each node's **parent** when it is first discovered. The parent Map doubles as the visited set: `parent.has(next)` means already seen.

```javascript
const parent = new Map([[start, null]]);
// in the BFS loop, for each neighbor:
if (!parent.has(next)) {
  parent.set(next, node);
  queue.push(next);
}
```

After BFS, walk back from the target to the start and reverse:

```javascript
const path = [];
for (let node = target; node !== null; node = parent.get(node)) {
  path.push(node);
}
path.reverse();
```

The distance is `path.length - 1` edges. A target with no parent entry is unreachable.

Several shortest paths can tie, and BFS takes neighbors in list order. Sort every neighbor list once before searching, and BFS always reports the same path: the one that comes first alphabetically when you compare nodes from the start. Keep the head-index queue (`queue[head++]`), since `shift()` is O(n).

For weighted edges, such as distances in miles, BFS is not enough. Dijkstra's algorithm is the next step: a simple version repeatedly scans a Map for the closest unvisited node.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const edgeCount = Number(lines[0]);
const routes = lines.slice(1, edgeCount + 1).map((line) => line.trim().split(/\s+/));
const queries = lines.slice(edgeCount + 1).map((line) => line.trim().split(/\s+/));

function addEdge(graph, a, b) {
  if (!graph.has(a)) {
    graph.set(a, []);
  }
  if (!graph.has(b)) {
    graph.set(b, []);
  }
  graph.get(a).push(b);
  graph.get(b).push(a);
}

function shortestPath(graph, start, target) {
  const parent = new Map([[start, null]]);
  const queue = [start];
  let head = 0;
  while (head < queue.length) {
    const node = queue[head++];
    if (node === target) {
      break;
    }
    for (const next of graph.get(node)) {
      if (!parent.has(next)) {
        parent.set(next, node);
        queue.push(next);
      }
    }
  }
  if (!parent.has(target)) {
    return null;
  }
  const path = [];
  for (let node = target; node !== null; node = parent.get(node)) {
    path.push(node);
  }
  return path.reverse();
}

const graph = new Map();
for (const [a, b] of routes) {
  addEdge(graph, a, b);
}
for (const neighbors of graph.values()) {
  neighbors.sort((a, b) => a.localeCompare(b));
}

for (const [from, to] of queries) {
  const path = shortestPath(graph, from, to);
  if (path === null) {
    console.log(`${from} to ${to}: no route`);
  } else {
    const flights = path.length - 1;
    console.log(`${path.join(" -> ")} (${flights} ${flights === 1 ? "flight" : "flights"})`);
  }
}

