const input = require("fs").readFileSync(0, "utf8");
const pairs = input.trim().split("\n").map((line) => line.trim().split(/\s+/));

function courseOrder(pairs) {
  const graph = new Map();
  const inDegree = new Map();
  for (const [before, after] of pairs) {
    for (const node of [before, after]) {
      if (!graph.has(node)) {
        graph.set(node, []);
        inDegree.set(node, 0);
      }
    }
    graph.get(before).push(after);
    inDegree.set(after, inDegree.get(after) + 1);
  }

  const ready = [...graph.keys()].filter((node) => inDegree.get(node) === 0);
  const order = [];
  while (ready.length > 0) {
    ready.sort((a, b) => a.localeCompare(b));
    const node = ready.shift();
    order.push(node);
    for (const next of graph.get(node)) {
      inDegree.set(next, inDegree.get(next) - 1);
      if (inDegree.get(next) === 0) {
        ready.push(next);
      }
    }
  }
  return order.length === graph.size ? order : null;
}

const order = courseOrder(pairs);
console.log(order === null ? "impossible" : order.join(" -> "));

